from __future__ import annotations

import os
import threading
from pathlib import Path
from typing import Callable


class FileWatcher:
    """
    Polls a file *or* directory for Python-source changes and calls
    ``callback()`` on every detected change.

    - **File mode** — watches a single path's mtime.
    - **Directory mode** — recursively scans all ``*.py`` files under the
      given directory and triggers when *any* of them is newer than the
      previously recorded maximum mtime.

    Uses only the Python standard library — no watchdog, no inotify.
    The poll runs in a daemon thread so it never prevents process exit.

    Usage::

        # Watch a single file
        watcher = FileWatcher("counter/main.py", on_change, interval=0.4)
        watcher.start()

        # Watch an entire project directory
        watcher = FileWatcher("counter/", on_change, interval=0.4)
        watcher.start()

        ...
        watcher.stop()
    """

    def __init__(
        self,
        path: str | Path,
        callback: Callable[[], None],
        interval: float = 0.4,
    ) -> None:
        self._path = str(path)
        self._callback = callback
        self._interval = interval
        self._is_dir = os.path.isdir(self._path)
        self._mtime = self._read_mtime()
        self._stop = threading.Event()
        self._thread = threading.Thread(target=self._loop, daemon=True)

    def start(self) -> "FileWatcher":
        """Start the background poll thread. Returns self for chaining."""
        self._thread.start()
        return self

    def stop(self) -> None:
        """Signal the poll thread to exit on its next iteration."""
        self._stop.set()

    @property
    def is_running(self) -> bool:
        return self._thread.is_alive()

    def _read_mtime(self) -> float:
        if self._is_dir:
            return self._scan_dir_mtime()
        try:
            return os.path.getmtime(self._path)
        except OSError:
            return 0.0

    def _scan_dir_mtime(self) -> float:
        """Return the maximum mtime across all ``*.py`` files under *_path*."""
        best = 0.0
        try:
            for root, _, files in os.walk(self._path):
                for fname in files:
                    if fname.endswith(".py"):
                        try:
                            t = os.path.getmtime(os.path.join(root, fname))
                            if t > best:
                                best = t
                        except OSError:
                            pass
        except OSError:
            pass
        return best

    def _loop(self) -> None:
        while not self._stop.wait(self._interval):
            mtime = self._read_mtime()
            if mtime != self._mtime:
                self._mtime = mtime
                try:
                    self._callback()
                except Exception:
                    pass
